require_once __DIR__.'/lib.php';$posts=array_reverse(load_json('posts.json',[]));$comments=load_json('comments.json',[]);$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {check_csrf();$name=trim($_POST['name']??'');$message=trim($_POST['message']??'');$postId=trim($_POST['post_id']??'');if($name===''||$message==='')$error='Please enter your name and message.';elseif(mb_strlen($message)>2500)$error='Message is too long (maximum 2,500 characters).';else{$comments[]= ['id'=>bin2hex(random_bytes(8)),'name'=>$name,'message'=>$message,'post_id'=>$postId,'created'=>date('c'),'from_admin'=>current_user()!==null,'admin_name'=>current_user()['name']??''];save_json('comments.json',$comments);flash('Your message has been posted to the discussion.');redirect('discussion.php'.($postId?'?post='.urlencode($postId):''));}}
$flash=flash();$selected=$_GET['post']??'';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Customer Discussion | AISON PROMOTIONZ</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">AP</span><span>AISON <b>PROMOTIONZ</b><small>WE MAKE IT HAPPENS</small></span></a><nav class="nav"><a href="index.php#services">Services</a><a href="index.php#updates">Updates</a><a class="nav-admin" href="admin.php">Admin login</a></nav></header><main class="discussion-page"><div class="discussion-intro"><p class="eyebrow">LET'S TALK</p><h1>Customer <span>discussion</span></h1><p>Ask about our services, events, promotions or collaborations. The AISON PROMOTIONZ team can reply here.</p></div><?php if($flash):?><div class="success"><?=h($flash)?></div><?php endif;?><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?><div class="discussion-layout"><section class="panel message-panel"><p class="eyebrow">JOIN THE CONVERSATION</p><h2>Send us a message</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Your name<input name="name" maxlength="80" required value="<?=h(current_user()['name']??'')?>" placeholder="How should we address you?"></label><label>Message<textarea name="message" rows="5" maxlength="2500" required placeholder="Type your question or comment here…"></textarea></label><label>Related update (optional)<select name="post_id"><option value="">General enquiry</option><?php foreach($posts as $p):?><option value="<?=h($p['id'])?>" <?=$selected===($p['id']??'')?'selected':''?>><?=h($p['title'])?></option><?php endforeach;?></select></label><button class="btn btn-orange" type="submit">Post message ↗</button></form><p class="small-note">Please keep messages respectful. Do not post passwords or private financial information.</p></section><section class="panel conversation-panel"><div class="split-heading"><div><p class="eyebrow">COMMUNITY</p><h2>Recent messages</h2></div><span class="role-pill"><?=count($comments)?> messages</span></div><?php $shown=array_reverse($comments);if($selected)$shown=array_values(array_filter($shown,fn($c)=>($c['post_id']??'')===$selected));if(!$shown):?><div class="empty-state compact"><div class="empty-symbol">✉</div><h3>Be the first to start a conversation</h3><p>Post a message and our team will be able to see it.</p></div><?php else:foreach(array_slice($shown,0,80) as $c):?><article class="comment"><div class="comment-top"><span class="avatar <?=!empty($c['from_admin'])?'avatar-admin':''?>"><?=h(strtoupper(substr($c['name']??'?',0,1)))?></span><div><strong><?=h($c['name']??'Visitor')?> <?php if(!empty($c['from_admin'])):?><em class="admin-tag">AISON TEAM</em><?php endif;?></strong><small><?=h(date('M j, Y · g:i a',strtotime($c['created']??'now')))?></small></div></div><p><?=nl2br(h($c['message']??''))?></p><?php if(!empty($c['post_id'])):?><small class="related-label">Related to: <?php foreach($posts as $p)if(($p['id']??'')===$c['post_id'])echo h($p['title']);?></small><?php endif;?></article><?php endforeach;endif;?></section></div></main><footer class="footer simple-footer"><div><strong>AISON PROMOTIONZ</strong><p>We make it happens · +256 777 271 886</p></div><a href="index.php">Back to home ↑</a></footer></body></html>
